head.script:
scwin.trigger1_onclick = async function(e) {
    //alert(wframe1.setSrc("wframe_Dynamic_SKT-375_(WSQ-1004)_sub.xml"));
    if (WebSquare._async === true) {
        log = await wframe1.setSrc("wframe_Dynamic_SKT-375_(WSQ-1004)_sub.xml");
    } else {
        log = wframe1.setSrc("wframe_Dynamic_SKT-375_(WSQ-1004)_sub.xml");
    }
};
scwin.trigger2_onclick = async function(e) {
    //alert(wframe1.setSrc("SKT-375_none.xml"));
    if (WebSquare._async === true) {
        log1 = await wframe1.setSrc("SKT-375_none.xml");
    } else {
        log1 = wframe1.setSrc("SKT-375_none.xml");
    }
};
scwin.checkVal1 = function() {
    return log == true;
}
scwin.checkVal2 = function() {
    return log1 == false;
}
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 setSrc("SKT-375_sub.xml") 버튼을 클릭한다.
    //1. In your browser, click the setSrc ("SKT-375_sub.xml") button.
    //Verify step 1. A popup window named True is created.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    //Test step 2. setSrc('SKT-375_none..xml') 버튼을 클릭한다.
    //2. Click the setSrc ('SKT-375_none..xml') button.
    //Verify step 2. A pop-up window called False is created.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = ""; window.log1 = "";
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 28-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
